/* @lc app=leetcode id=2565 lang=kotlin */ class Solution { fun minimumScore(s: String, t: String): Int = IntArray(t.length + 1) { s.length + 1 }.let { suf -> t.indices.reversed().fold(s.length - 1) { i, j -> (i downTo 0).find { s[it] == t[j] }?.also { suf[j] = it }?.let { it - 1 } ?: -2 }.let { s.indices.fold(Triple(t.indices.find { suf[it] < s.length } ?: t.length, 0, t.indices.find { suf[it] < s.length } ?: t.length)) { (ans, p1, p2), i -> if (p1 < t.length && s[i] == t[p1]) (p1 + 1).let { np1 -> generateSequence(maxOf(p2, np1)) { it + 1 }.first { it >= t.length || suf[it] > i }.let { np2 -> Triple(minOf(ans, np2 - np1), np1, np2) } } else Triple(ans, p1, p2) }.first } } }